"""Original editable street prop kit, generated by Blender bpy (no external assets)."""
import runpy
import math
import json
from pathlib import Path
import bpy

if not bpy.app.background:
    raise RuntimeError('Background mode required; interactive projects are never cleared')

kit=runpy.run_path(str(Path(__file__).with_name('generate_assets.py')))
box=kit['box']
base=kit['BASE']
out=base/'godot/assets'
source=base/'art/source'
out.mkdir(parents=True,exist_ok=True)
source.mkdir(parents=True,exist_ok=True)
manifest={}

def cylinder(name,at,radius,depth,material,side=False):
    bpy.ops.mesh.primitive_cylinder_add(vertices=12,radius=radius,depth=depth,location=at)
    obj=bpy.context.object
    obj.name=name
    if side: obj.rotation_euler.x=math.pi/2
    obj.data.materials.append(kit['MATS'][material])
    return obj

def finish(name,merge=True):
    if merge:
        kit['join']([o for o in bpy.context.scene.objects if o.type=='MESH'],'DD_'+name)
    triangles=0
    meshes=0
    for obj in bpy.context.scene.objects:
        if obj.type=='MESH':
            obj.data.calc_loop_triangles()
            triangles+=len(obj.data.loop_triangles)
            meshes+=1
    kit['SURFACES']['project_uvs']()
    bpy.ops.wm.save_as_mainfile(filepath=str(source/(name+'.blend')))
    bpy.ops.export_scene.gltf(filepath=str(out/(name+'.glb')),export_format='GLB',export_yup=True,export_texcoords=True)
    kit['SURFACES']['canonical_uvs'](out/(name+'.glb'))
    manifest[name]={'file':name+'.glb','source':'art/source/'+name+'.blend','triangles':triangles,'meshes':meshes}
    print('STREET_ASSET_OK',name,triangles,flush=True)

kit['reset']()
def coachwork(name,stations,material):
    # Designed longitudinal sections: tapered ends, shoulder line and rolled sill.
    vertices=[];faces=[]
    for x,w,bottom,top in stations:
        vertices += [(x,-w*.82,bottom),(x,-w,bottom+.09),(x,-w,top-.07),(x,-w*.85,top),
                     (x,w*.85,top),(x,w,top-.07),(x,w,bottom+.09),(x,w*.82,bottom)]
    for j in range(len(stations)-1):
        for i in range(8):faces.append((j*8+i,j*8+(i+1)%8,(j+1)*8+(i+1)%8,(j+1)*8+i))
    faces += [tuple(reversed(range(8))),tuple(range((len(stations)-1)*8,len(stations)*8))]
    mesh=bpy.data.meshes.new(name);mesh.from_pydata(vertices,[],faces)
    obj=bpy.data.objects.new(name,mesh);bpy.context.collection.objects.link(obj)
    mesh.materials.append(kit['MATS'][material])
    return obj
coachwork('PressedBody',[(-1.74,.61,.35,.71),(-1.48,.74,.32,.82),(-.9,.75,.32,.86),(.8,.75,.32,.82),(1.48,.71,.35,.73),(1.74,.60,.38,.67)],'cloth')
coachwork('SlopingGlazing',[(-1.04,.64,.81,.84),(-.63,.55,.83,1.34),(.30,.53,.82,1.35),(.91,.64,.79,.83)],'glass')
coachwork('CrownRoof',[(-.66,.55,1.30,1.34),(-.4,.56,1.32,1.39),(.24,.54,1.32,1.38),(.35,.52,1.30,1.34)],'cloth')
for y in [-.67,.67]:
    box('WindowDivider',(-.12,y,1.06),(.055,.045,.46),'steel',.01)
    for x in [-.55,.52]:
        box('DoorHandle',(x,y*1.12,.77),(.16,.035,.025),'steel',.009)
    box('Sill',(0,y*1.10,.35),(2.8,.055,.07),'steel',.02)
for x in [-1.08,1.08]:
    for y in [-.77,.77]:
        cylinder('Tyre',(x,y,.36),.34,.18,'boots',True)
        cylinder('Hub',(x,y*1.13,.36),.17,.02,'steel',True)
for y in [-.51,.51]:
    box('Headlight',(1.72,y,.70),(.06,.32,.16),'cream',.015)
    box('TailLight',(-1.72,y,.70),(.06,.29,.12),'cross',.01)
box('Bumper',(1.78,0,.43),(.12,1.5,.14),'steel',.015)
for y in [-.747,.747]:
    box('SillCorrosion',(-.75,y,.44),(.48,.012,.07),'rust',.009)
    box('WheelLipCorrosion',(1.14,y,.67),(.32,.014,.045),'rust',.009)
box('BonnetSeam',(1.10,0,.766),(.015,1.20,.008),'boots')
box('FrontGrille',(1.755,0,.55),(.03,.60,.12),'boots',.015)
finish('abandoned_car')

kit['reset']()
box('Base',(0,0,.07),(.28,.28,.14),'steel',.02)
cylinder('Pole',(0,0,1.48),.055,2.8,'steel')
box('Arm',(.36,0,2.82),(.78,.08,.09),'steel',.015)
box('Housing',(.73,0,2.74),(.43,.27,.13),'steel',.025)
box('DD_Lamp_Lens',(.73,0,2.665),(.33,.19,.025),'cream',.008)
finish('street_lamp',False)

kit['reset']()
for x in [-.95,.95]:
    box('Post',(x,0,.53),(.14,.14,1.06),'wood',.02)
for z in [.30,.76]:
    box('Rail',(0,0,z),(2.0,.075,.10),'wood_light',.012)
for i in range(7):
    obj=box('Slat',(-.75+i*.25,-.055,.52),(.15,.06,.88 if i!=3 else .50),'wood_light',.012)
    if i==3: obj.rotation_euler.y=.20
finish('fence_panel')

kit['reset']()
cylinder('Bin',(0,0,.43),.27,.80,'steel')
cylinder('Lid',(0,0,.85),.30,.07,'boots')
box('Handle',(0,0,.925),(.18,.05,.08),'steel',.01)
for x in [-.29,.29]:
    box('Grip',(x,0,.67),(.05,.14,.06),'steel')
finish('trash_bin')

kit['reset']()
for i in range(30):
    angle=i*2.399963
    radius=.035+.19*((i*7%29)/29)**.5
    x,y=math.cos(angle)*radius,math.sin(angle)*radius
    height=.12+(i%7)*.027
    width=.009+(i%3)*.003
    lean=.035+(i%5)*.018
    dx,dy=math.cos(angle)*lean,math.sin(angle)*lean
    mesh=bpy.data.meshes.new('Blade')
    # Narrow folded blades bend at mid-height instead of rigid triangular spikes.
    across=(-math.sin(angle)*width,math.cos(angle)*width)
    vertices=[]
    for shift,level,scale in [(0,0,1),(.30,.57,.65)]:
        cx,cy=x+dx*shift,y+dy*shift
        vertices += [(cx-across[0]*scale,cy-across[1]*scale,height*level),
                     (cx+across[0]*scale,cy+across[1]*scale,height*level),
                     (cx+math.cos(angle)*.004,cy+math.sin(angle)*.004,height*level+.003)]
    vertices.append((x+dx,y+dy,height))
    faces=[(0,2,1),(3,4,6),(4,5,6),(5,3,6)]
    for k in range(3):
        n=(k+1)%3
        faces += [(k,n,n+3),(k,n+3,k+3)]
    mesh.from_pydata(vertices,[],faces)
    obj=bpy.data.objects.new('GrassBlade',mesh)
    bpy.context.collection.objects.link(obj)
    mesh.materials.append(kit['MATS']['wood_light' if i%9==0 else 'jacket'])
finish('grass_clump')

kit['reset']()
for i in range(4):
    bpy.ops.mesh.primitive_ico_sphere_add(subdivisions=1,radius=.10,location=(i*.16-.25,math.sin(i)*.13,.055))
    obj=bpy.context.object
    obj.name='Rubble'
    obj.scale.z=.6
    obj.data.materials.append(kit['MATS']['steel'])
for i in range(3):
    obj=box('DiscardedPaper',(i*.18-.2,-.16,.012),(.16,.22,.012),'cream')
    obj.rotation_euler.z=i*.7
finish('road_debris')

# Thin visual ground dressing; never adds an invisible step to the walkable plane.
kit['reset']()
for name,color in [('paving',(.43,.43,.38,1)),('soil',(.33,.32,.23,1)),('asphalt',(.25,.28,.29,1)),('crack',(.17,.19,.18,1))]:
    mat=bpy.data.materials.new('DD_'+name)
    linear=tuple(c/12.92 if c<=.04045 else ((c+.055)/1.055)**2.4 for c in color[:3])+(1,)
    mat.diffuse_color=linear
    mat.node_tree.nodes.get('Principled BSDF').inputs['Base Color'].default_value=linear
    mat.node_tree.nodes.get('Principled BSDF').inputs['Roughness'].default_value=.98
    alias={'paving':'concrete','soil':'soil','asphalt':'road_patch'}.get(name)
    if alias:
        definition=kit['MATERIAL_LIBRARY']['materials'][alias]
        shader=mat.node_tree.nodes.get('Principled BSDF')
        shader.inputs['Roughness'].default_value=definition['roughness']
        kit['SURFACES']['apply'](mat,dict(definition,id=alias),kit['ROOT'])
    kit['MATS'][name]=mat
world=json.loads((kit['ROOT']/'godot/data/rules.json').read_text(encoding='utf-8'))['world_bounds']
left=world['min_x']+.5
length=world['max_x']-world['min_x']-1
for i in range(round(length/.5)):
    # Godot z .12..1.0: leave door leaves and all furniture collisions untouched.
    box('PavingSlab',(left+.25+i*.5,-.55,.022),(.485,.86,.035),'paving')
    vertices=[]
    for x in [left+.25+i*.5-.2425,left+.25+i*.5+.2425]:
        vertices += [(x,y,z) for y,z in [(-1.06,.005),(-1.06,.055),(-1.04,.075),(-.96,.075),(-.94,.055),(-.94,.005)]]
    faces=[(j,(j+1)%6,(j+1)%6+6,j+6) for j in range(6)]
    faces += [tuple(reversed(range(6))),tuple(range(6,12))]
    mesh=bpy.data.meshes.new('KerbProfile');mesh.from_pydata(vertices,[],faces)
    obj=bpy.data.objects.new('ChamferedKerb',mesh);bpy.context.collection.objects.link(obj);mesh.materials.append(kit['MATS']['paving'])
def ground_polygon(name,points,material):
    mesh=bpy.data.meshes.new(name)
    mesh.from_pydata([(x,-z,.037) for x,z in points],[],[tuple(range(len(points)))])
    obj=bpy.data.objects.new(name,mesh);bpy.context.collection.objects.link(obj)
    mesh.materials.append(kit['MATS'][material])
for side in [-1,1]:
    z=5.5 if side==1 else .96
    for i in range(round(length)):
        x=left+.5+i
        width=.09+.035*(i%3)
        # Uneven worn tongues interrupt the formerly rectangular road/soil border.
        ground_polygon('BrokenRoadEdge',[(x-.53,z-width*.4),(x-.21,z-width),
            (x+.34,z-width*.55),(x+.53,z+width*.15),(x+.12,z+width),
            (x-.35,z+width*.65)],'soil')
for i in range(int(length/2.7)):
    x=-11+i*2.7;z=1.6+(i%3)*1.1
    ground_polygon('SettledRepair',[(x-.58,z-.18),(x+.15,z-.23),(x+.65,z-.04),(x+.57,z+.26),(x-.31,z+.31),(x-.63,z+.10)],'asphalt')
# Connected settlement fractures, with branches instead of identical scattered ticks.
for network in range(4):
    px=-11+network*6.0;pz=1.5+network%2*1.7
    for segment in range(11):
        nx=px+.42;nz=pz+math.sin(segment*1.9+network)*.12
        ground_polygon('ConnectedFracture',[(px,pz-.008),(nx,nz-.008),(nx,nz+.008),(px,pz+.008)],'crack')
        if segment in [3,7]:
            ground_polygon('FractureBranch',[(px,pz),(px+.36,pz+.42),(px+.37,pz+.43),(px+.012,pz)],'crack')
        px,pz=nx,nz
finish('street_ground')
(out/'street_manifest.json').write_text(json.dumps({'version':1,'assets':manifest},indent=2)+'\n',encoding='utf-8',newline='\n')
print('STREET_ART_PIPELINE_OK',flush=True)
